sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {  
    // Return early if the form is loading or the new value is empty  
    if (isLoading || newValue === '') {  
        return;  
    }  

    // Create a GlideAjax instance to call the server-side script  
    var ga = new GlideAjax('lmsGlide');  
    ga.addParam('sysparm_name', 'getLeaveBucket');  
    ga.addParam('sysparm_user', g_user.userID);  
    ga.addParam('sysparm_leavetype', newValue);  

    // Fetch data asynchronously from the server  
    ga.getXML(getBucket);  

    // Callback function to handle the response from the server  
    function getBucket(response) {  
        var answer = response.responseXML.documentElement.getAttribute("answer");  

         // Attempt to parse the JSON response  

            var result = JSON.parse(answer);  
            // Set fields on the form with the response data  
            g_form.setValue('accrued', result.accrued || 0);  
            g_form.setValue('balance', result.balance || 0);  
            g_form.setValue('taken', result.taken || 0);  

    }  
}
